function publishState() {
  const cx = canvas.width / 2;
  const cy = canvas.height / 2;
  const radius = player.ring === 0 ? INNER_RADIUS : OUTER_RADIUS;
  const x = cx + Math.cos(player.angle) * radius;
  const y = cy + Math.sin(player.angle) * radius;
  window.__game = {
    state: phase === 'playing' ? 'playing' : 'gameover',
    score,
    player: {
      x,
      y,
      visible: x >= 0 && x <= canvas.width && y >= 0 && y <= canvas.height,
    },
    objective: "Swap the dot between inner and outer rings to pass through gaps.",
  };
}
